// Generated by scripts/make_kz_map.py from Natural Earth data (public domain). Do not edit by hand.
// Equirectangular projection, x scaled by cos(48°), matching kz-pixel-map.svg.

export const MAP_WIDTH = 660
export const MAP_HEIGHT = 375

const LON0 = 46.0
const LAT1 = 56.1
const SCALE = 23.484631
const COS_PHI = 0.669131

/** Projects longitude/latitude to map units (0..MAP_WIDTH, 0..MAP_HEIGHT). */
export function project(lat: number, lng: number): { x: number; y: number } {
  return { x: (lng - LON0) * COS_PHI * SCALE, y: (LAT1 - lat) * SCALE }
}
